import{at as e,it as t,n,vt as r}from"./chunks/framework.DdRMjwGS.js";var i=JSON.parse(`{"title":"健康与可观测性","description":"","frontmatter":{},"headers":[],"relativePath":"backend/health-observability.md","filePath":"backend/health-observability.md","lastUpdated":1794566617000}`),a={name:`backend/health-observability.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="健康与可观测性" tabindex="-1">健康与可观测性 <a class="header-anchor" href="#健康与可观测性" aria-label="Permalink to “健康与可观测性”">​</a></h1><p>本页说明健康检查、维护模式、服务监控、链路关联与弹性限制，适用于运维人员与后端开发者。</p><h2 id="健康检查" tabindex="-1">健康检查 <a class="header-anchor" href="#健康检查" aria-label="Permalink to “健康检查”">​</a></h2><p>宿主 <code>MapXiHanHealth()</code> 映射三个探针端点，直接对应框架的应用状态机。三者只给总状态（<code>status</code>、<code>state</code>），只是判定不同：通过 200，否则 503。探针不经过内核管道、匿名可访问，所以不带各 Feature 与健康项的详情（框架 ADR-0209），详情见下文的<a href="#服务监控">服务监控</a>。</p><table tabindex="0"><thead><tr><th>端点</th><th>用途</th><th>通过条件</th></tr></thead><tbody><tr><td><code>/health/startup</code></td><td>启动探针</td><td>所有 Feature 都已启动完毕</td></tr><tr><td><code>/health/ready</code></td><td>就绪探针</td><td>应用处于 Ready 或 Degraded</td></tr><tr><td><code>/health/live</code></td><td>存活探针</td><td>应用没有 Failed</td></tr></tbody></table><p>单个 Feature 的启动超时是 <code>XiHan:Kernel:StartTimeoutSeconds</code>（BasicApp 取 60 秒，表结构升级与开发环境建表都在启动阶段完成），失败策略见 <code>XiHan:Kernel:FailurePolicy</code>。</p><p>健康项由各 Provider 自带（框架 ADR-0030），BasicApp 不另写。常见的有：</p><table tabindex="0"><thead><tr><th>健康项</th><th>来源</th></tr></thead><tbody><tr><td><code>persistence.sqlsugar.database</code></td><td>平台库；配了从库另有 <code>persistence.sqlsugar.replicas</code>（有从库不可读时 Degraded）</td></tr><tr><td><code>scheduling.database.leader</code></td><td>调度的领导租约表，不可达时 Degraded</td></tr><tr><td><code>workflow.database.poller</code></td><td>工作流到期书签的轮询</td></tr><tr><td><code>objectstorage.store.&lt;名&gt;</code></td><td>Files 存储配置对应的每个命名实例</td></tr><tr><td><code>persistence.datasource.&lt;名&gt;</code></td><td>代码生成登记的外部数据源（<code>codegen-&lt;ID&gt;</code>），连不上 Degraded</td></tr><tr><td><code>localization.database.translations</code></td><td>数据库译文：还没加载为 Started，加载失败为 Degraded 并保留上一份快照</td></tr><tr><td><code>ai.vectordata.store</code></td><td>配了 Qdrant 时的知识库向量库，连不上 Degraded</td></tr><tr><td><code>caching.redis.connection</code> / <code>messaging.rabbitmq.connection</code></td><td>配了 Redis / RabbitMQ 时：启动时连不上即启动失败，之后按 <code>HealthProbeIntervalSeconds</code>（15 秒）重探，断开时 Degraded、应用照常服务</td></tr><tr><td><code>caching.inmemory.capacity</code> / <code>messaging.inmemory.capacity</code></td><td>没配 Redis / RabbitMQ 时的进程内实现的容量</td></tr></tbody></table><p>以服务监控里实际列出的为准。条目带 <code>description</code>、<code>checkedAt</code>、<code>durationMs</code> 与 <code>data</code>；多数健康项的重探间隔在各自配置节的 <code>HealthProbeIntervalSeconds</code>，见<a href="./../configuration">配置参考</a>。</p><h2 id="维护模式" tabindex="-1">维护模式 <a class="header-anchor" href="#维护模式" aria-label="Permalink to “维护模式”">​</a></h2><p>另一个节点升级共享库时，<code>MaintenanceModeMiddleware</code>（宿主排在最前）对除健康检查与 <code>/.well-known/</code> 之外的请求返回 503（<code>RUNTIME_UNAVAILABLE_003</code>，带 <code>Retry-After</code>），普通端点与 Hub 也一样挡住。判定依据是平台库的版本台账：有节点持着没过期的升级锁即进入维护模式；只看 PostgreSQL 库，台账还没建或读不到时不进入。健康端点不受拦截，升级期间负载均衡仍能探测。升级本身见<a href="./upgrade">表结构升级</a>。</p><h2 id="服务监控" tabindex="-1">服务监控 <a class="header-anchor" href="#服务监控" aria-label="Permalink to “服务监控”">​</a></h2><p>Maintenance 的 <code>server.get</code>（<code>GET /api/server</code>，<code>maintenance.server.read</code>，平台侧）：运行信息取自框架的 <code>IHostMonitor</code>（<code>Observability.Abstractions</code>，不启动外部命令），包括 .NET 运行时与进程、处理器、内存、磁盘、网卡、显卡、主板与 BIOS，另附各 Provider 最近一次的健康项。读不到的字段为空（区分「没有」与「为零」）；CPU 使用率与网卡速率由后台按 <code>XiHan:Observability:Host:SampleIntervalSeconds</code>（5 秒）采样，启动后第一个采样间隔内为空。前端页面 <code>/maintenance/server</code>。</p><p><code>server.packages</code>（<code>GET /api/server:packages</code>，同一权限，平台侧）给关于页的后端依赖清单：已加载的 <code>XiHan*</code> 程序集直接引用的第三方程序集与版本，不含 <code>XiHan</code>、<code>Microsoft</code>、<code>System</code> 开头的，同名取最高版本。</p><h2 id="链路与日志" tabindex="-1">链路与日志 <a class="header-anchor" href="#链路与日志" aria-label="Permalink to “链路与日志”">​</a></h2><table tabindex="0"><thead><tr><th>能力</th><th>做法</th></tr></thead><tbody><tr><td>Trace</td><td>前端每个请求带 W3C <code>traceparent</code>；缺失或不合法时框架并入 ASP.NET Core 当前的请求 Activity，也没有时生成新的 trace-id</td></tr><tr><td>关联</td><td>失败响应的 Problem Details 带 <code>traceId</code>；成功响应不另带 trace 头，以客户端自己生成的 <code>traceparent</code> 为准</td></tr><tr><td>业务日志</td><td>审计日志与按 trace-id 的链路时间线，见<a href="./logging">日志审计</a></td></tr><tr><td>结构化日志</td><td>ASP.NET Core <code>ILogger</code>，<code>appsettings.json</code> 的 <code>Logging</code> 节；Development 把 <code>XiHan</code> 调到 <code>Debug</code></td></tr><tr><td>OpenTelemetry</td><td>Full Profile 带 <code>Observability.OpenTelemetry</code>：追踪、指标与日志缺省都开（<code>XiHan:Observability:OpenTelemetry</code>），配了 OTLP 端点（<code>Otlp:Endpoint</code> 或环境变量 <code>OTEL_EXPORTER_OTLP_ENDPOINT</code>）才导出</td></tr></tbody></table><p>命令模式下日志只写 stderr，stdout 只承载命令输出，方便脚本处理。</p><h2 id="弹性" tabindex="-1">弹性 <a class="header-anchor" href="#弹性" aria-label="Permalink to “弹性”">​</a></h2><p>框架内核的 Resilience 阶段按操作 ID 提供固定窗口限流、并发上限与熔断（<code>XiHan:Kernel:Resilience</code>，根上的键是默认策略，<code>Operations:&lt;操作 ID&gt;</code> 按操作覆盖）。缺省不限流、不限并发、不熔断。拒绝以 503 返回：限流 <code>KERNEL_UNAVAILABLE_002</code>、并发超限 <code>KERNEL_UNAVAILABLE_003</code>、熔断 <code>KERNEL_UNAVAILABLE_004</code>。</p><p>截止时间由请求头 <code>xihan-deadline</code>（绝对时间）携带，gRPC 用 <code>grpc-timeout</code>；超时即 504（<code>KERNEL_TIMEOUT_001</code>）。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to “下一步”">​</a></h2><ul><li><a href="./../deployment">部署</a> · <a href="./logging">日志审计</a> · <a href="./upgrade">表结构升级</a></li></ul>`,22)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};